import * as React from "react"
import { navigate } from "gatsby"
import Seo from "../components/Seo"
import AuthShell, { AuthLink } from "../components/auth/AuthShell"
import { ArrowRight } from "../components/Icons"
import { NOT_CONFIGURED, configured, humanError, supabase } from "../lib/supabase"
import { useAuth } from "../context/auth"
import * as s from "../components/auth/Auth.module.css"
import { affiliateFor } from "../lib/affiliate"

/**
 * Signing in — MTC-FCS-008.
 *
 * ── IT REMEMBERS WHERE YOU WERE GOING ──────────────────────────────────────
 * `?next=/buy` sends you back there afterwards, so being bounced to sign in
 * halfway through buying does not also lose your place. The value is checked
 * to be a path on this site: an open redirect on a login page is a phishing
 * tool, because the URL a victim checks is genuinely ours.
 *
 * ── ONE MESSAGE FOR A WRONG EMAIL AND A WRONG PASSWORD ─────────────────────
 * "That email and password do not match an account" — never which half was
 * wrong. Telling somebody the email was right confirms the account exists.
 */

/** Only same-site paths. Anything else falls back to the account page. */
function safeNext(raw) {
  const value = String(raw || "")
  if (!value.startsWith("/") || value.startsWith("//")) return "/account"
  return value
}

const LogInPage = ({ location }) => {
  const [email, setEmail] = React.useState("")
  const [password, setPassword] = React.useState("")
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")

  const { user, ready } = useAuth()
  const available = configured()
  const next = safeNext(new URLSearchParams(location?.search || "").get("next"))

  /* ── WHERE SIGNING IN TAKES YOU — FCS-068 ──────────────────────────────
     An explicit `?next=` always wins: somebody bounced here from a page they
     asked for goes back to it. Otherwise it depends on WHO signed in, because
     the two kinds of account have nothing to do with each other — a marketer
     landing on a contractor's account page has no website there and no
     numbers, and has to go and find the right page themselves.

     Asked after the session exists rather than guessed from the address, and
     `/account` remains the answer for anybody who is not a marketer, including
     when the check itself fails. */
  const asked = new URLSearchParams(location?.search || "").get("next")

  React.useEffect(() => {
    if (!ready || !user) return

    // Somebody bounced here from a page they asked for goes back to it.
    if (asked) {
      navigate(next, { replace: true })
      return
    }

    let alive = true
    affiliateFor(user).then(role => {
      if (!alive) return
      navigate(role.status === "active" ? "/affiliate" : next, { replace: true })
    })

    return () => {
      alive = false
    }
  }, [ready, user, next, asked])

  const submit = async e => {
    e.preventDefault()
    if (busy) return
    setError("")

    const client = supabase()
    if (!client) {
      setError(NOT_CONFIGURED)
      return
    }

    setBusy(true)
    const { error: err } = await client.auth.signInWithPassword({
      email: email.trim(),
      password,
    })
    setBusy(false)

    if (err) {
      setError(humanError(err))
      return
    }

    /* No navigation here on purpose — FCS-068. The session lands a moment
       later and the effect above decides where this person belongs, which
       needs one round trip to find out whether they are a marketer.
       Navigating here as well simply won the race every time, and the answer
       it won with was the wrong one. */
  }

  return (
    <AuthShell
      title="Log in"
      lead="Welcome back."
      notice={available ? null : NOT_CONFIGURED}
      footer={
        <>
          No account yet? <AuthLink to="/sign-up">Create one</AuthLink>
          {" · "}
          {/* MTC-FCS-035: the one path that does not depend on an email
              arriving, put where somebody stuck will actually look. */}
          <AuthLink to="/help/cannot-log-in">Paid but cannot get in?</AuthLink>
        </>
      }
    >
      <form onSubmit={submit}>
        <div className={s.fields}>
          <div className={s.field}>
            <label htmlFor="li-email">Email address</label>
            <input
              id="li-email"
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              autoComplete="email"
              required
              disabled={!available || busy}
            />
          </div>
          <div className={s.field}>
            <label htmlFor="li-password">Password</label>
            <input
              id="li-password"
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              autoComplete="current-password"
              required
              disabled={!available || busy}
            />
          </div>
        </div>

        <button
          type="submit"
          className={`btn btn--lg ${s.submit}`}
          disabled={!available || busy || !email.trim() || !password}
        >
          {busy ? "Signing you in…" : "Log in"}
          {!busy && <ArrowRight className="btn__arrow" />}
        </button>

        {error ? <p className={s.error}>{error}</p> : null}
      </form>
    </AuthShell>
  )
}

export const Head = () => <Seo title="Log in" description="Log in to Free Contractor Services." />

export default LogInPage
