import * as React from "react"
import { graphql, useStaticQuery } from "gatsby"

/**
 * `noindex` is for pages that exist but are nobody's business to find: the
 * admin workbench, and the help page for somebody locked out (which is only
 * useful arriving from a receipt or from us). It is a request, not a control —
 * anything genuinely private needs the gate, not the meta tag.
 */
const Seo = ({ title, description, noindex = false }) => {
  const { site } = useStaticQuery(graphql`
    query {
      site {
        siteMetadata {
          title
          description
          siteUrl
        }
      }
    }
  `)

  const meta = site.siteMetadata
  const pageTitle = title ? `${title} | ${meta.title}` : meta.title
  const desc = description || meta.description

  return (
    <>
      <html lang="en" />
      <title>{pageTitle}</title>
      <meta name="description" content={desc} />
      <meta property="og:title" content={pageTitle} />
      <meta property="og:description" content={desc} />
      <meta property="og:type" content="website" />
      <meta property="og:url" content={meta.siteUrl} />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="theme-color" content="#1668e8" />
      {noindex ? <meta name="robots" content="noindex, nofollow" /> : null}
    </>
  )
}

export default Seo
